// Streaming Service - serves HLS/DASH manifests
var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<StreamDbContext>(opt =>
    opt.UseCosmos(
        accountEndpoint: builder.Configuration["Azure:Cosmos:Endpoint"],
        accountKey: builder.Configuration["Azure:Cosmos:Key"],
        databaseName: "YoutubeStreamingDb"
    )
);
builder.Services.AddStackExchangeRedisCache(opt =>
    opt.Configuration = builder.Configuration.GetConnectionString("Redis")
);
builder.Services.AddMassTransit(opt =>
    opt.UsingAzureServiceBus((context, cfg) => {
        cfg.Host(builder.Configuration["Azure:ServiceBus:ConnectionString"]);
        cfg.ConfigureEndpoints(context);
    })
);

var app = builder.Build();
app.MapGet("/api/stream/{videoId}/manifest", async.GetManifest);
app.MapGet("/api/stream/{videoId}/segment/{quality}/{segment}", async.GetSegment);
app.MapGet("/api/live/{channelId}/playlist", async.GetLivePlaylist);
app.Run();
